// Wave 26 Pass H.4 — health watchdog state machine
// HMAC computed HERE (Code node has Node.js require); HTTP nodes downstream read $json.signature
const crypto = require('crypto');
const staticData = $getWorkflowStaticData('global');
staticData.consecutiveFails ??= 0;
staticData.lastRestartAt ??= 0;
staticData.lastDiscordAt ??= 0;

const resp = $input.first().json;
const status = resp.statusCode ?? resp.status ?? 0;
const isHealthy = status === 200 && resp.body?.status === 'ok';
const now = Date.now();

let action = 'noop';
let detail = `health_status=${status} healthy=${isHealthy}`;

if (isHealthy) {
  if (staticData.consecutiveFails > 0) {
    detail += ` recovered_after=${staticData.consecutiveFails}_fails`;
    action = 'recovered';
  }
  staticData.consecutiveFails = 0;
} else {
  staticData.consecutiveFails++;
  detail += ` consecutive_fails=${staticData.consecutiveFails}`;
  if (staticData.consecutiveFails >= 3 && (now - staticData.lastRestartAt) > 5 * 60 * 1000) {
    action = 'restart';
    staticData.lastRestartAt = now;
  }
  if (staticData.consecutiveFails >= 5 && (now - staticData.lastDiscordAt) > 15 * 60 * 1000) {
    action = action === 'restart' ? 'restart_and_alert' : 'alert';
    staticData.lastDiscordAt = now;
  }
}

// Pre-compute HMAC payload so HTTP node (sandboxed, no require) can read it via $json.signature
const timestamp = Math.floor(now / 1000);
const reason = 'watchdog_3_consecutive_fails';
const secret = $env.ADMIN_RESTART_HMAC_SECRET || 'unset';
const signature = crypto.createHmac('sha256', secret).update(`${timestamp}:${reason}`).digest('hex');

return [{ json: { action, detail, consecutiveFails: staticData.consecutiveFails, healthBody: resp.body ?? null, timestamp, reason, signature } }];

